const D = { scale: 1, energy: .6, hue: 210, speed: 1, density: .5, chub: .5, x: .5, y: .74, seed: 0, pose: 'auto', style: 'poster', act: 'set' };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const fr = i => { const q = Math.sin(i * 127.1 + P.seed * 311.7) * 43758.5453; return q - Math.floor(q); };
const TAU = 6.28318530718;
const u = Math.min(width, height);
const s = u * 0.0019 * P.scale;

let bt = K.beat * P.speed;
const sb = ((bt % 1) + 1) % 1;
if (S.lastBeat == null || bt < S.lastBeat) S.lastBeat = bt;
S.lastBeat = bt;
const am = .82 + .22 * Math.sin(K.t * .31 + fr(6) * 6);
const loco = (.72 + .5 * K.intensity) * am;                  // energy-independent locomotion floor
const eAmp = (.35 + .65 * P.energy) * (.6 + .55 * K.intensity) * am;
const kick = Math.min(1, K.pulse * (.5 + .5 * K.intensity) + A.bass * .75);
S.rms = (S.rms || 0) * .85 + (A.rms || 0) * .15;
S.tre = (S.tre || 0) * .8 + (A.treble || 0) * .2;

// ---- seed-dependent freckle/dot jitter cache ----
if (S.seedUsed !== P.seed) { S.seedUsed = P.seed; S.pat = null; }

// ---- pose dramaturgy ----
const ACTS = {
  set:   ['waddle','dj','waddle','slide','dj','dance','waddle','dj'],
  chill: ['idle','waddle','idle','dj','idle','waddle','idle','slide'],
  party: ['dance','waddle','dance','slide','dj','dance','slide','dance'] };
let pose = P.pose;
if (pose === 'auto') pose = (ACTS[P.act] || ACTS.set)[((K.section % 8) + 8) % 8];

const slow1 = Math.sin(K.t * .53 + fr(2) * 6);
const slow2 = Math.sin(K.t * .37 + fr(4) * 6);

let dy = 0, sway = 0, tilt = 0, lean = 0;
let liftL = 0, liftR = 0, flipL = .28, flipR = .28, headT = 0, beak = 0, deck = 0;

if (pose === 'idle') {
  sway = Math.sin(bt * Math.PI / 3) * 11 * loco;
  dy = -Math.abs(Math.sin(bt * Math.PI)) * 3 * loco + Math.sin(K.t * 1.4) * 2.4;
  tilt = Math.sin(bt * Math.PI / 3) * .06 * loco;
  headT = Math.sin(K.t * .7) * .13 + K.swell * .05 * eAmp;
  flipL = .26 + Math.sin(bt * Math.PI) * .16 * eAmp;
  flipR = .26 - Math.sin(bt * Math.PI) * .16 * eAmp;
  const lift = fr(Math.floor(K.t * .6) + 3) < .18 ? Math.max(0, Math.sin((K.t * .6 % 1) * Math.PI * 2)) * 9 : 0;
  liftL = lift;
  beak = fr(Math.floor(K.t * .8) + 9) < .12 ? .5 : 0;
} else if (pose === 'waddle') {
  const side = (((Math.floor(bt) % 2) + 2) % 2 === 0) ? 1 : -1;
  const w = Math.sin(sb * Math.PI);
  sway = side * 17 * w * loco;
  tilt = side * .14 * w * loco;
  dy = -Math.abs(Math.sin(bt * Math.PI)) * 5 * loco;
  liftR = side > 0 ? Math.max(0, w) * 15 : 0;
  liftL = side < 0 ? Math.max(0, w) * 15 : 0;
  headT = side * .09 * w + Math.sin(bt * TAU) * .05 * eAmp;
  flipL = .3 + side * .22 * w; flipR = .3 - side * .22 * w;
  beak = fr(Math.floor(bt) + 20) < .25 ? kick * .5 : 0;
} else if (pose === 'dj') {
  lean = 12;
  const scr = Math.sin(bt * Math.PI * 4) * (.55 + .45 * kick);
  flipR = 1.15 + scr; flipL = .5 + Math.sin(bt * Math.PI) * .1;
  headT = Math.sin(bt * TAU) * .15 * (.6 + eAmp) + kick * .1;
  dy = -kick * 4 - Math.abs(Math.sin(bt * Math.PI)) * 4 * loco;
  sway = Math.sin(bt * Math.PI / 2) * 7 * loco;
  tilt = .07;
  beak = kick * .45;
  deck = 1;
} else if (pose === 'slide') {
  sway = Math.sin(bt * Math.PI / 2) * 34 * loco;
  tilt = .48 + Math.sin(bt * Math.PI) * .1 * loco;
  dy = 28 + Math.sin(bt * Math.PI * 2) * 3;
  lean = 4;
  flipL = -.55 + Math.sin(bt * Math.PI * 2) * .22;
  flipR = -.55 - Math.sin(bt * Math.PI * 2) * .22;
  liftL = Math.max(0, Math.sin(bt * Math.PI * 2)) * 10;
  liftR = Math.max(0, -Math.sin(bt * Math.PI * 2)) * 10;
  headT = -.18;
  beak = .3 + kick * .3;
} else {                                                     // dance
  dy = -(kick * 11 + Math.abs(Math.sin(sb * Math.PI)) * 6) * eAmp;
  const alt = (((Math.floor(bt) % 2) + 2) % 2 === 0) ? 1 : -1;
  flipL = 1.55 + alt * .3 * eAmp; flipR = 1.55 - alt * .3 * eAmp;
  sway = alt * 11 * Math.sin(sb * Math.PI) * loco;
  tilt = alt * .09 * eAmp;
  headT = Math.sin(bt * TAU) * .11;
  beak = kick * .55;
}

// universal slow drift (guarantees non-static even when beat motion aliases)
dy += slow1 * 3;
sway += slow2 * 4.5;
tilt += Math.sin(K.t * .21 + fr(8) * 6) * .028;

// ---- style ----
const styles = ['poster', 'riso', 'noir', 'wire'];
const st = styles.indexOf(P.style) >= 0 ? P.style : 'poster';
const wire = st === 'wire';
const H = ((P.hue % 360) + 360) % 360;
const chub = P.chub;
const bodyW = .84 + chub * .42;
const jig = Math.sin(bt * TAU + fr(1) * 6) * chub * (3 + 5 * Math.min(1, Math.abs(dy) / 8)) * eAmp;
const bellyW = .96 + jig * .012;

function paint(role) {
  noStroke();
  if (wire) {
    noFill();
    stroke(role === 'belly' ? 190 : (role === 'beak' || role === 'foot') ? 30 : 202, 55, 34, 92);
    strokeWeight((role === 'skel' ? 1.1 : 1.7) * s);
    return;
  }
  if (st === 'noir') {
    if (role === 'back') fill(H, 34, 11);
    else if (role === 'belly') fill(H, 14, 33);
    else if (role === 'beak' || role === 'foot') fill(28, 66, 40);
    else if (role === 'eye') fill(0, 0, 3);
    else if (role === 'eyeW') fill(0, 0, 66);
    else fill(H, 30, 15);
    return;
  }
  if (st === 'riso') {
    if (role === 'back') fill(H, 58, 42, 90);
    else if (role === 'belly') fill(44, 20, 96, 90);
    else if (role === 'beak' || role === 'foot') fill(20, 86, 96, 92);
    else if (role === 'eye') fill(H, 62, 20, 96);
    else if (role === 'eyeW') fill(0, 0, 100, 92);
    else fill(H, 52, 46, 90);
    return;
  }
  // poster (default flat screenprint)
  if (role === 'back') fill(H, 44, 20);
  else if (role === 'belly') fill(42, 12, 97);
  else if (role === 'beak' || role === 'foot') fill(28, 90, 98);
  else if (role === 'eye') fill(0, 0, 8);
  else if (role === 'eyeW') fill(0, 0, 100);
  else fill(H, 42, 24);
}

// build halftone dot pattern once (riso texture)
function ensurePat() {
  if (S.pat && S.patKey === (P.seed + '|' + Math.round(s * 100))) return;
  const g = createGraphics(14, 14);
  g.colorMode(HSB, 360, 100, 100, 100);
  g.noStroke(); g.clear();
  g.fill(H, 70, 30, 100); g.ellipse(7, 7, 5.5, 5.5);
  S.pat = drawingContext.createPattern(g.canvas, 'repeat');
  S.patKey = P.seed + '|' + Math.round(s * 100);
}

const ax = P.x * width + sway * s;
const ay = P.y * height;
const pump = 1 + S.rms * .35 * P.energy;

// ground shadow
noStroke(); fill(0, 0, 0, wire ? 0 : 24);
ellipse(P.x * width, ay + 128 * s, Math.max(14, 120 * bodyW - Math.abs(sway) * .3) * s, 15 * s);

push();
translate(ax, ay + (dy + lean * .3) * s);
rotate(tilt);
scale(pump, pump);

// deck (dj prop)
if (deck && !wire) {
  push(); translate(64 * s, 40 * s);
  paint('foot'); noStroke(); fill(0, 0, 12); ellipse(0, 0, 78 * s, 30 * s);
  fill(H, 20, 55); ellipse(0, 0, 60 * s, 22 * s);
  fill(0, 0, 8); ellipse(0, 0, 12 * s, 5 * s);
  pop();
}

// feet
paint('foot');
push(); translate(-30 * s, (118 - liftL) * s); rotate(-.05 - liftL * .01);
if (wire) { paint('foot'); ellipse(0, 0, 40 * s, 16 * s); } else { triangle(-20 * s, 6 * s, 20 * s, 6 * s, 0, -8 * s); ellipse(0, 5 * s, 40 * s, 12 * s); }
pop();
push(); translate(30 * s, (118 - liftR) * s); rotate(.05 + liftR * .01);
if (wire) { ellipse(0, 0, 40 * s, 16 * s); } else { triangle(-20 * s, 6 * s, 20 * s, 6 * s, 0, -8 * s); ellipse(0, 5 * s, 40 * s, 12 * s); }
pop();

// far flipper (behind body)
paint('back');
push(); translate(-70 * bodyW * s, -8 * s); rotate(-flipL - .1);
ellipse(0, 34 * s, 30 * s, 96 * s);
pop();

// poster offset shadow-ink
if (st === 'poster') { noStroke(); fill(H, 52, 11); ellipse(7 * s, 8 * s, 152 * bodyW * s, 250 * s); }

// body / back mass
paint('back');
ellipse(0, -8 * s, 150 * bodyW * s, 250 * s);
if (wire) { paint('skel'); line(0, -128 * s, 0, 116 * s); ellipse(0, -8 * s, 108 * bodyW * s, 190 * s); ellipse(0, -8 * s, 66 * bodyW * s, 130 * s); }

// belly patch
paint('belly');
if (!wire) ellipse(0, 26 * s, 104 * bodyW * bellyW * s, 186 * s);
else ellipse(0, 26 * s, 104 * bodyW * bellyW * s, 186 * s);

// halftone over body (riso only)
if (st === 'riso') {
  ensurePat();
  if (S.pat) {
    drawingContext.save();
    drawingContext.globalCompositeOperation = 'multiply';
    drawingContext.globalAlpha = .28;
    drawingContext.fillStyle = S.pat;
    drawingContext.fillRect(-85 * bodyW * s, -140 * s, 170 * bodyW * s, 280 * s);
    drawingContext.restore();
  }
  // second-ink misregistration edge
  noStroke(); fill((H + 30) % 360, 70, 88, 26);
  ellipse(-4 * s, -12 * s, 150 * bodyW * s, 250 * s);
}

// near flipper (in front)
paint('back');
push(); translate(70 * bodyW * s, -8 * s); rotate(flipR + .1);
ellipse(0, 34 * s, 30 * s, 96 * s);
if (wire) { paint('skel'); line(0, 0, 0, 60 * s); }
pop();

// head details region (top of the mass): eyes + beak
push();
translate(0, -72 * s + Math.sin(bt * TAU) * 1.6 * s * eAmp);
rotate(headT);

// beak (orange), opens with `beak`
const bo = beak * 9 * s;
paint('beak');
if (wire) {
  triangle(-5 * s, -2 * s - bo * .4, 5 * s, -2 * s - bo * .4, 0, -18 * s);
  triangle(-6 * s, 3 * s + bo, 6 * s, 3 * s + bo, 0, 16 * s + bo);
} else {
  triangle(-7 * s, -2 * s - bo * .4, 7 * s, -2 * s - bo * .4, 0, -20 * s);
  triangle(-8 * s, 3 * s + bo, 8 * s, 3 * s + bo, 0, 18 * s + bo);
  if (bo > 1.5 * s) { noStroke(); fill(2, 80, 40); ellipse(0, 2 * s, 10 * s, bo); }
}

// eyes
const blink = ((K.t * .27 + fr(9)) % 1) < .045;
const exo = 21 * bodyW * s;
const gx = (fr(Math.floor(K.t * .4) + 11) - .5) * 3 * s;
if (blink && !wire) {
  paint('eye'); stroke(0, 0, st === 'noir' ? 4 : 8); strokeWeight(2 * s); noFill();
  line(-exo - 5 * s, -30 * s, -exo + 5 * s, -30 * s);
  line(exo - 5 * s, -30 * s, exo + 5 * s, -30 * s);
  noStroke();
} else {
  paint('eyeW'); ellipse(-exo, -30 * s, 15 * s, 17 * s); ellipse(exo, -30 * s, 15 * s, 17 * s);
  paint('eye'); ellipse(-exo + gx, -30 * s, 8 * s, 9 * s); ellipse(exo + gx, -30 * s, 8 * s, 9 * s);
  if (!wire && st !== 'noir') { noStroke(); fill(0, 0, 100, 90); ellipse(-exo + gx - 2 * s, -33 * s, 3 * s, 3 * s); ellipse(exo + gx - 2 * s, -33 * s, 3 * s, 3 * s); }
}
pop();

pop();

// ambient snow/spark motes (density) — behind-agnostic, cheap
if (P.density > 0.02 && !wire) {
  const n = Math.round(P.density * 22);
  noStroke();
  for (let i = 0; i < n; i++) {
    const ph = (K.t * (.12 + fr(i + 50) * .18) + fr(i + 70)) % 1;
    const fx = (fr(i + 90) - .5) * u * 1.1 + P.x * width;
    const fy = ((ph + fr(i + 110)) % 1) * u * .9 + (P.y * height - u * .55);
    const tw = .5 + .5 * Math.sin(K.t * 3 + i);
    fill(st === 'noir' ? H : 50, st === 'noir' ? 12 : 8, 100, (14 + 22 * tw) * (.4 + .6 * P.density));
    ellipse(fx, fy, (2 + 2.4 * tw + S.tre * 6) * s, (2 + 2.4 * tw) * s);
  }
}
